def load() -> pd.DataFrame:
    import pandas as pd
    path = "data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Metropolitan_Areas_Fraud_and_Other_Reports.csv"
    # File appears to contain non-UTF8 characters; try Windows-1252, fall back to latin1.
    try:
        return pd.read_csv(path, encoding="cp1252")
    except UnicodeDecodeError:
        return pd.read_csv(path, encoding="latin1")

